import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel b8bd735:
# packet.ContainerOpen{WindowID: 120, ContainerType: 12, ContainerPosition: protocol.BlockPos{1, 70, -3},
# ContainerEntityUniqueID: 300}
HORSE = bytes.fromhex("780c028c0105d804")

# generated by gophertunnel b8bd735:
# packet.ContainerOpen{WindowID: 255, ContainerType: 247, ContainerPosition: protocol.BlockPos{0, 0, 0},
# ContainerEntityUniqueID: -1}
NONE = bytes.fromhex("fff700000001")

GOLDENS = [
    pytest.param(
        v2168.ContainerOpenPacket(
            container_id=v2168.ContainerID.ARMOR,
            type=v2168.ContainerType.HORSE,
            pos=v2168.BlockPos(x=1, y=70, z=-3),
            entity_unique_id=300,
        ),
        HORSE,
        id="horse",
    ),
    pytest.param(
        v2168.ContainerOpenPacket(
            container_id=v2168.ContainerID.NONE,
            type=v2168.ContainerType.NONE,
            pos=v2168.BlockPos(x=0, y=0, z=0),
            entity_unique_id=-1,
        ),
        NONE,
        id="sentinels",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_container_open_is_packet_46(version):
    assert version.PACKETS[46] is version.ContainerOpenPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_container_open_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_container_open_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_container_open_rejects_a_body_without_the_target_actor_id():
    with pytest.raises(ValueError, match="at byte"):
        v2168.ContainerOpenPacket.from_bytes(HORSE[:6])
